  ollama: { baseUrl: 'http://host.docker.internal:11434/v1', model: 'llama3.1', fastModel: '', keyVar: '' },
  custom: { baseUrl: '', model: '', fastModel: '', keyVar: '' },
};

const DEPTHS = {
  quick: { label: 'Skim', subq: 3, queriesPerSubq: 2, perSource: 8, rounds: 1, screenTop: 36, minPerSubq: 2, include: 10, fullText: 4, auditMax: 12, words: '700 to 900' },
  standard: { label: 'Survey', subq: 4, queriesPerSubq: 2, perSource: 10, rounds: 2, screenTop: 48, minPerSubq: 3, include: 16, fullText: 8, auditMax: 24, words: '1200 to 1600' },
  deep: { label: 'Exhaustive', subq: 5, queriesPerSubq: 3, perSource: 12, rounds: 3, screenTop: 60, minPerSubq: 4, include: 24, fullText: 12, auditMax: 40, words: '1800 to 2400' },
};

function getConfig() {
  const explicit = envGet('LLM_PROVIDER').toLowerCase();
  let provider = explicit;
  if (!provider) {
    if (envGet('ANTHROPIC_API_KEY')) provider = 'anthropic';
    else if (envGet('OPENAI_API_KEY')) provider = 'openai';
    else if (envGet('GEMINI_API_KEY')) provider = 'gemini';
    else if (envGet('OPENROUTER_API_KEY')) provider = 'openrouter';
    else if (envGet('LLM_BASE_URL')) provider = 'custom';
    else provider = 'none';
  }
  const d = PROVIDER_DEFAULTS[provider] || PROVIDER_DEFAULTS.custom;
  const apiKey = envGet('LLM_API_KEY') || (d.keyVar ? envGet(d.keyVar) : '');
  const model = envGet('LLM_MODEL', d.model);
  const llm = {
    provider,
    baseUrl: envGet('LLM_BASE_URL', d.baseUrl).replace(/\/+$/, ''),
    apiKey,
    model,
    fastModel: envGet('LLM_FAST_MODEL', d.fastModel || model),
  };
  llm.ready = provider !== 'none' && !!llm.baseUrl && !!llm.model && (!!apiKey || provider === 'ollama' || provider === 'custom');

  // Optional dense embeddings for hybrid retrieval (BM25 is always on).
  const embMode = envGet('EMBEDDINGS_PROVIDER', 'auto').toLowerCase();
  let embeddings = null;
  if (embMode !== 'off' && embMode !== 'none') {
    const pick = embMode === 'auto' ? (envGet('OPENAI_API_KEY') ? 'openai' : envGet('GEMINI_API_KEY') ? 'gemini' : '') : embMode;
    if (pick === 'openai' && envGet('OPENAI_API_KEY')) {
      embeddings = { baseUrl: 'https://api.openai.com/v1', apiKey: envGet('OPENAI_API_KEY'), model: envGet('EMBEDDINGS_MODEL', 'text-embedding-3-small'), dimensions: 256 };
    } else if (pick === 'gemini' && envGet('GEMINI_API_KEY')) {
      embeddings = { baseUrl: PROVIDER_DEFAULTS.gemini.baseUrl, apiKey: envGet('GEMINI_API_KEY'), model: envGet('EMBEDDINGS_MODEL', 'gemini-embedding-001'), dimensions: 256 };
    } else if (pick === 'custom' && envGet('EMBEDDINGS_BASE_URL')) {
      embeddings = { baseUrl: envGet('EMBEDDINGS_BASE_URL').replace(/\/+$/, ''), apiKey: envGet('EMBEDDINGS_API_KEY'), model: envGet('EMBEDDINGS_MODEL'), dimensions: parseInt(envGet('EMBEDDINGS_DIMENSIONS', '0'), 10) || undefined };
    }
  }

  return {
    llm,
    embeddings,
    contactEmail: envGet('CONTACT_EMAIL', ''),
    keys: {
      openalex: envGet('OPENALEX_API_KEY'),
      semanticScholar: envGet('SEMANTIC_SCHOLAR_API_KEY'),
    },
    urls: {
      openalex: envGet('OPENALEX_URL', 'https://api.openalex.org').replace(/\/+$/, ''),
      arxiv: envGet('ARXIV_URL', 'https://export.arxiv.org').replace(/\/+$/, ''),
      semanticScholar: envGet('SEMANTIC_SCHOLAR_URL', 'https://api.semanticscholar.org').replace(/\/+$/, ''),
      europepmc: envGet('EUROPEPMC_URL', 'https://www.ebi.ac.uk').replace(/\/+$/, ''),
      arxivPdf: envGet('ARXIV_PDF_URL', 'https://arxiv.org/pdf').replace(/\/+$/, ''),
    },
  };
}

// ─── LLM client: Anthropic + any OpenAI-compatible endpoint ─────────────────

function parseJSONLoose(text) {
  let s = String(text || '').trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  const firstObj = s.indexOf('{');
  const firstArr = s.indexOf('[');
  let start = -1;
  if (firstObj === -1) start = firstArr;
  else if (firstArr === -1) start = firstObj;
  else start = Math.min(firstObj, firstArr);
  if (start === -1) throw new Error('No JSON found in model output');
  const open = s[start];
  const close = open === '{' ? '}' : ']';
  const end = s.lastIndexOf(close);
  let body = s.slice(start, end + 1);
  try {
    return JSON.parse(body);
  } catch (e) {
    // Common repairs: trailing commas, smart quotes.
    body = body.replace(/,\s*([}\]])/g, '$1').replace(/[“”]/g, '"');
    return JSON.parse(body);
  }
}

async function llm({ system = '', prompt, json = false, tier = 'main', maxTokens = 2500, temperature = 0.3, timeout = 240000 }) {
  const C = getConfig().llm;
  if (!C.ready) {
    throw new Error('No language model is configured. Set ANTHROPIC_API_KEY, OPENAI_API_KEY, GEMINI_API_KEY or OPENROUTER_API_KEY (or LLM_PROVIDER + LLM_BASE_URL + LLM_MODEL) in .env and restart.');
  }
  const model = tier === 'fast' ? C.fastModel || C.model : C.model;
  const sys = json
    ? (system ? system + '\n\n' : '') + 'Respond with one valid JSON object and nothing else: no prose before or after, no code fences.'
    : system;
  let text = '';
  RT.usage.calls += 1;

  if (C.provider === 'anthropic') {
    const res = await http({
      method: 'POST',
      url: C.baseUrl + '/v1/messages',
      headers: { 'x-api-key': C.apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model, max_tokens: maxTokens, system: sys || undefined, temperature, messages: [{ role: 'user', content: prompt }] },
      timeout,
      retries: 3,
    });
    text = (res.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
    if (res.usage) {
      RT.usage.inputTokens += res.usage.input_tokens || 0;
      RT.usage.outputTokens += res.usage.output_tokens || 0;
    }
  } else {
    const messages = [];
    if (sys) messages.push({ role: 'system', content: sys });
    messages.push({ role: 'user', content: prompt });
    const body = { model, messages };
    const reasoning = C.provider === 'openai' && /^(gpt-5|o\d)/i.test(model);
    if (reasoning) {
      body.max_completion_tokens = maxTokens + 6000;
      body.reasoning_effort = 'low';
    } else {
      body.max_tokens = maxTokens;
      body.temperature = temperature;
    }
    if (json && (C.provider === 'openai' || C.provider === 'gemini')) body.response_format = { type: 'json_object' };
    const headers = { 'content-type': 'application/json' };
    if (C.apiKey) headers.authorization = 'Bearer ' + C.apiKey;
    if (C.provider === 'openrouter') {
      headers['HTTP-Referer'] = 'https://github.com/marginalia-research';
      headers['X-Title'] = 'Marginalia';
    }
    const res = await http({ method: 'POST', url: C.baseUrl + '/chat/completions', headers, body, timeout, retries: 3 });
    const msg = (res.choices && res.choices[0] && res.choices[0].message) || {};
    text = Array.isArray(msg.content) ? msg.content.map((p) => p.text || '').join('') : msg.content || '';
    if (res.usage) {
      RT.usage.inputTokens += res.usage.prompt_tokens || 0;
      RT.usage.outputTokens += res.usage.completion_tokens || 0;
    }
  }

  if (!json) return String(text).trim();
  try {
    return parseJSONLoose(text);
  } catch (e) {
    const fixed = await llm({
      system: 'You repair malformed JSON. Output only the corrected JSON.',
      prompt: 'Fix this so it is valid JSON, keeping all content:\n\n' + String(text).slice(0, 14000),
      tier: 'fast',
      maxTokens,
    });
    return parseJSONLoose(fixed);
  }
}

/** Merge this node's LLM usage into the running state. */
function recordUsage(state) {
  state.usage = state.usage || { calls: 0, inputTokens: 0, outputTokens: 0 };
  state.usage.calls += RT.usage.calls;
  state.usage.inputTokens += RT.usage.inputTokens;
  state.usage.outputTokens += RT.usage.outputTokens;
  RT.usage = { calls: 0, inputTokens: 0, outputTokens: 0 };
}

async function embedTexts(texts) {
  const E = getConfig().embeddings;
  if (!E || !texts.length) return null;
  const out = [];
  for (const batch of chunkArray(texts, 64)) {
    const body = { model: E.model, input: batch.map((t) => String(t).slice(0, 6000)) };
    if (E.dimensions) body.dimensions = E.dimensions;
    const res = await http({
      method: 'POST',
      url: E.baseUrl + '/embeddings',
      headers: { authorization: 'Bearer ' + E.apiKey, 'content-type': 'application/json' },
      body,
      timeout: 60000,
      retries: 2,
    });
    for (const row of res.data || []) out.push((row.embedding || []).map((x) => Math.round(x * 1000) / 1000));
  }
  return out.length === texts.length ? out : null;
}

// ─── Text: tokenising, BM25 retrieval, chunking, citations ──────────────────

const STOP = new Set(('a about above after again against all am an and any are as at be because been before being below between both but by can could did do does doing down during each few for from further had has have having he her here hers herself him himself his how i if in into is it its itself just me more most my myself no nor not now of off on once only or other our ours ourselves out over own same she should so some such than that the their theirs them themselves then there these they this those through to too under until up very was we were what when where which while who whom why will with would you your yours yourself yourselves also however thus using based use used via within without among across may might must shall study studies paper results result show shows shown method methods approach approaches new et al').split(' '));

function stem(w) {
  if (w.length > 5 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 5 && w.endsWith('ing')) return w.slice(0, -3);
  if (w.length > 4 && w.endsWith('ed') && !w.endsWith('eed')) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !w.endsWith('ss') && !w.endsWith('us') && !w.endsWith('is')) return w.slice(0, -1);
  return w;
}

function tokenize(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/-/g, ' ')
    .split(/\s+/)
    .filter((w) => w.length > 2 && !STOP.has(w) && !/^\d+$/.test(w))
    .map(stem);
}

function countMap(tokens) {
  const m = new Map();
  for (const t of tokens) m.set(t, (m.get(t) || 0) + 1);
  return m;
}

function buildBM25(docs) {
  const toks = docs.map((d) => tokenize(d.text));
  const tfs = toks.map(countMap);
  const df = new Map();
  for (const tf of tfs) for (const t of tf.keys()) df.set(t, (df.get(t) || 0) + 1);
  const N = docs.length || 1;
  const avgdl = toks.reduce((s, t) => s + t.length, 0) / N || 1;
  return { docs, tfs, lens: toks.map((t) => t.length), df, N, avgdl };
}

function bm25Search(index, query, k = 10, filter) {
  const q = uniq(tokenize(query));
  const k1 = 1.4;
  const b = 0.72;
  const scored = [];
  for (let i = 0; i < index.docs.length; i++) {
    if (filter && !filter(index.docs[i])) continue;
    const tf = index.tfs[i];
    let s = 0;
    for (const t of q) {
      const f = tf.get(t);
      if (!f) continue;
      const n = index.df.get(t) || 0;
      const idf = Math.log(1 + (index.N - n + 0.5) / (n + 0.5));
      s += idf * ((f * (k1 + 1)) / (f + k1 * (1 - b + (b * index.lens[i]) / index.avgdl)));
    }
    if (s > 0) scored.push({ doc: index.docs[i], score: s, i });
  }
  scored.sort((x, y) => y.score - x.score);
  return scored.slice(0, k);
}

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

/**
 * Hybrid retrieval over chunks: BM25 always, plus dense vectors when the
 * chunks carry them. Fused with reciprocal-rank fusion.
 */
async function retrieve(chunks, query, k = 8, filter) {
  const index = buildBM25(chunks);
  const lexical = bm25Search(index, query, Math.max(k * 3, 30), filter);
  const hasVectors = chunks.length && Array.isArray(chunks[0].v);
  if (!hasVectors) return lexical.slice(0, k).map((r) => r.doc);
  let qv = null;
  try { qv = (await embedTexts([query]) || [])[0]; } catch (e) { qv = null; }
  if (!qv) return lexical.slice(0, k).map((r) => r.doc);
  const dense = chunks
    .map((c, i) => ({ doc: c, i, score: filter && !filter(c) ? -1 : cosine(qv, c.v) }))
    .filter((r) => r.score > 0)
    .sort((x, y) => y.score - x.score)
    .slice(0, Math.max(k * 3, 30));
  const fused = new Map();
  lexical.forEach((r, rank) => fused.set(r.i, (fused.get(r.i) || 0) + 1 / (60 + rank)));
  dense.forEach((r, rank) => fused.set(r.i, (fused.get(r.i) || 0) + 1 / (60 + rank)));
  return Array.from(fused.entries()).sort((x, y) => y[1] - x[1]).slice(0, k).map(([i]) => chunks[i]);
}

function cleanPdfText(text) {
  let t = String(text || '')
    .replace(/\r/g, '')
    .replace(/(\w)-\n(\w)/g, '$1$2')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n');
  const m = t.match(/\n\s*(references|bibliography|literature cited)\s*\n/gi);
  if (m) {
    const idx = t.toLowerCase().lastIndexOf(m[m.length - 1].toLowerCase());
    if (idx > t.length * 0.5) t = t.slice(0, idx);
  }
  return t.trim();
}

function splitSentences(text) {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .split(/(?<=[.!?])\s+(?=[A-Z0-9“"(\[])/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function chunkText(text, size = 1100, overlap = 160, maxChunks = 80) {
  const sentences = splitSentences(text);
  const chunks = [];
  let cur = '';
  for (const s of sentences) {
    if ((cur + ' ' + s).length > size && cur) {
      chunks.push(cur.trim());
      if (chunks.length >= maxChunks) break;
      cur = cur.slice(-overlap) + ' ' + s;
    } else {
      cur += ' ' + s;
    }
  }
  if (cur.trim() && chunks.length < maxChunks) chunks.push(cur.trim());
  return chunks;
}

/** "[3]", "[3, 5]", "[3–5]", "[3][7]" → [3, 5, ...] */
function parseCitations(text) {
  const out = [];
  const re = /\[(\d+(?:\s*[-–,]\s*\d+)*)\]/g;
  let m;
  while ((m = re.exec(text))) {
    for (const part of m[1].split(',')) {
      const range = part.split(/[-–]/).map((x) => parseInt(x.trim(), 10));
      if (range.length === 2 && range[1] >= range[0] && range[1] - range[0] < 20) {
        for (let n = range[0]; n <= range[1]; n++) out.push(n);
      } else if (!isNaN(range[0])) out.push(range[0]);
    }
  }
  return uniq(out);
}

function sentenceKey(s) {
  return String(s || '').replace(/\[[\d,\s–-]+\]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 90);
}

function normTitle(t) {
  return String(t || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 90);
}

function jaccard(a, b) {
  const A = new Set(a), B = new Set(b);
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter || 1);
}

function stripTags(s) {
  return String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function decodeEntities(s) {
  return String(s || '')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
    .replace(/&amp;/g, '&');
}

// ─── Scholarly sources: OpenAlex, arXiv, Semantic Scholar, Europe PMC ───────

const SOURCE_LABELS = { openalex: 'OpenAlex', arxiv: 'arXiv', semanticscholar: 'Semantic Scholar', europepmc: 'Europe PMC' };

function cleanDoi(doi) {
  if (!doi) return '';
  return String(doi).toLowerCase().replace(/^https?:\/\/(dx\.)?doi\.org\//, '').replace(/^doi:/, '').trim();
}

function arxivIdFrom(str) {
  if (!str) return '';
  const s = String(str).toLowerCase();
  let m = s.match(/10\.48550\/arxiv\.(\d{4}\.\d{4,5})/);
  if (m) return m[1];
  m = s.match(/arxiv\.org\/(?:abs|pdf)\/(\d{4}\.\d{4,5})/);
  if (m) return m[1];
  m = s.match(/^(\d{4}\.\d{4,5})(v\d+)?$/);
  return m ? m[1] : '';
}

function emptyPaper() {
  return {
    key: '', title: '', authors: [], year: null, venue: '', abstract: '', tldr: '',
    doi: '', url: '', pdfUrl: '', citedBy: null, sources: [], ids: {}, refs: [], type: '', foundBy: [],
  };
}

function finishPaper(p) {
  p.doi = cleanDoi(p.doi);
  const ax = p.ids.arxiv || arxivIdFrom(p.doi) || arxivIdFrom(p.url);
  if (ax) {
    p.ids.arxiv = ax;
    if (!p.pdfUrl) p.pdfUrl = getConfig().urls.arxivPdf + '/' + ax;
    if (!p.url) p.url = 'https://arxiv.org/abs/' + ax;
  }
  if (!p.url && p.doi) p.url = 'https://doi.org/' + p.doi;
  p.title = decodeEntities(stripTags(p.title)).replace(/\s+/g, ' ').trim();
  p.abstract = clampText(decodeEntities(stripTags(p.abstract)), 2400);
  p.key = p.doi && !arxivIdFrom(p.doi) ? 'doi:' + p.doi : ax ? 'arxiv:' + ax : 'title:' + normTitle(p.title);
  return p;
}

// OpenAlex ------------------------------------------------------------------

function openAlexAbstract(inv) {
  if (!inv || typeof inv !== 'object') return '';
  const words = [];
  for (const [word, positions] of Object.entries(inv)) for (const pos of positions) words[pos] = word;
  return words.filter(Boolean).join(' ');
}

const OPENALEX_SELECT = 'id,doi,display_name,publication_year,authorships,primary_location,best_oa_location,cited_by_count,abstract_inverted_index,referenced_works,type,ids';

function fromOpenAlex(w) {
  const p = emptyPaper();
  p.title = w.display_name || w.title || '';
  p.year = w.publication_year || null;
  p.authors = (w.authorships || []).map((a) => a.author && a.author.display_name).filter(Boolean);
  p.venue = (w.primary_location && w.primary_location.source && w.primary_location.source.display_name) || '';
  p.abstract = openAlexAbstract(w.abstract_inverted_index);
  p.doi = w.doi || '';
  p.citedBy = typeof w.cited_by_count === 'number' ? w.cited_by_count : null;
  p.pdfUrl = (w.best_oa_location && w.best_oa_location.pdf_url) || (w.primary_location && w.primary_location.pdf_url) || '';
  p.url = (w.primary_location && w.primary_location.landing_page_url) || '';
  p.ids.openalex = String(w.id || '').replace('https://openalex.org/', '');
  if (w.ids && w.ids.pmid) p.ids.pmid = String(w.ids.pmid).replace(/\D/g, '');
  p.refs = (w.referenced_works || []).map((r) => String(r).replace('https://openalex.org/', ''));
  p.type = w.type || '';
  p.sources = ['openalex'];
  return finishPaper(p);
}

function openAlexAuth(C) {
  return { mailto: C.contactEmail || undefined, api_key: C.keys.openalex || undefined };
}

async function searchOpenAlex(q, n) {
  const C = getConfig();
  const res = await http({
    url: C.urls.openalex + '/works',
    query: { search: q, 'per-page': n, select: OPENALEX_SELECT, ...openAlexAuth(C) },
    timeout: 25000,
  });
  return (res.results || []).map(fromOpenAlex);
}

/** Snowballing: works that cite `id` (forward) and works `id` cites (backward). */
async function openAlexNeighbours(id, n = 6) {
  const C = getConfig();
  const common = { 'per-page': n, select: OPENALEX_SELECT, sort: 'cited_by_count:desc', ...openAlexAuth(C) };
  const [citing, cited] = await Promise.all([
    http({ url: C.urls.openalex + '/works', query: { ...common, filter: 'cites:' + id }, timeout: 25000 }).catch(() => ({ results: [] })),
    http({ url: C.urls.openalex + '/works', query: { ...common, filter: 'cited_by:' + id }, timeout: 25000 }).catch(() => ({ results: [] })),
  ]);
  return {
    citing: (citing.results || []).map(fromOpenAlex),
    references: (cited.results || []).map(fromOpenAlex),
  };
}

// arXiv -----------------------------------------------------------------------

function arxivQuery(q) {
  const terms = String(q).toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/).filter((w) => w.length > 2 && !STOP.has(w)).slice(0, 6);
  if (!terms.length) return 'all:' + encodeURIComponent(q);
  return terms.map((t) => 'all:' + t).join(' AND ');
}

function xmlTag(block, tag) {
  const m = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>', 'i'));
  return m ? decodeEntities(m[1]).trim() : '';
}

async function searchArxiv(q, n) {
  const C = getConfig();
  const xml = await http({
    url: C.urls.arxiv + '/api/query',
    query: { search_query: arxivQuery(q), start: 0, max_results: n, sortBy: 'relevance' },
    responseType: 'text',
    timeout: 30000,
  });
  const entries = String(xml).split(/<entry>/i).slice(1);
  return entries.map((e) => {
    const p = emptyPaper();
    const idUrl = xmlTag(e, 'id');
    p.ids.arxiv = arxivIdFrom(idUrl);
    p.title = xmlTag(e, 'title');
    p.abstract = xmlTag(e, 'summary');
    const published = xmlTag(e, 'published');
    p.year = published ? parseInt(published.slice(0, 4), 10) : null;
    p.authors = Array.from(e.matchAll(/<name>([\s\S]*?)<\/name>/gi)).map((m) => decodeEntities(m[1]).trim());
    p.doi = xmlTag(e, 'arxiv:doi');
